insert into o_jogo.packs (id, name, date_release, quantity, price) values
    (1, 'Amigue Secrete 2023', '2023-12-22', 5, 40),
    (2, 'Amigue Secrete 2024', '2024-12-20', 3, 50),
    (3, 'Amigue Secrete 2025', '2025-12-22', 4, 60);
insert into o_jogo.cards (id, id_pack, number, name, type, is_shot, text, level) values
    (1, 1, 1, 'A Bebida Infinita', 'shot', true, 'Foi descoberta uma fórmula mágica para beber infinitamente! Escolha 1 jogador para beber 1 shot, na vez dele, pelos próximos 3 turnos.', 2),
    (2, 1, 2, 'Festinha de Sexta', 'shot', true, 'Mais uma edição da festinha de sexta aconteceu, mas você não foi convidado. Todos bebem 1 shot, menos você.', 2),
    (3, 1, 3, 'Um Bom Companheiro', 'shot', true, 'A famosa tradição. Cante a musiquinha e escolha alguém para beber 1 shot.', 1),
    (4, 1, 4, 'Kitumbras', 'investigacao', true, 'Jp quer companhia para um kitumbras. Ao jogar, Sauzburg obrigatoriamente beberá 1 shot e os outros poderão escolher se querem beber ou não.', 3),
    (5, 1, 5, 'Cabeça Rachada', 'efeito', false, 'Jp, enfurecido, acaba de dar uma cabeçada em um taxista e fica maluco. Ao jogar, a missão de Sauzburg passa a ser ter menos shots entre todos os jogadores. A carta perde o efeito após uma troca de missão de Sauzburg.', 4),
    (6, 1, 6, 'É, Deve Ser', 'defesa', false, 'Por mais que tenham argumentos, você está completamente blindado. Diga "é, deve ser" e anule qualquer troca de missão que tentarem realizar com você ou outro jogador.', 2),
    (7, 1, 7, 'Livro do Brasa', 'shot', true, 'Você piscou e o Brasa lançou mais um livro!. Todos bebem 1 shot para comemorar.', 2),
    (8, 1, 8, 'O Pai do Grupo', 'shot', true, 'O Brasa é como um pai para todos nós e temos muito o que aprender com ele. Como um bom pai, ele está oferecendo 1 shotzinho para seus filhos. Escolha 3 jogadores para beberem 1 shot cada.', 2),
    (9, 1, 9, 'Brasa Negrão', 'investigacao', true, 'O Brasa falou novamente que é negro. Por conta disso, Swarley será identificado, beberá 1 shot e apontará outro jogador para beber 1 shot também.', 4),
    (10, 1, 10, 'César que Destruiu o Império', 'investigacao', false, 'César chegou e bagunçou tudo. Escolha outro jogador e, caso não seja o Swarley, troque de missão com ele. Caso seja o Swarley, a missão dele passa a ser ter mais shots que todos os outros jogadores. A carta perde o efeito após uma troca de missão de Swarley.', 4),
    (11, 1, 11, 'Não Posso, Tenho que Codar', 'defesa', false, 'Hoje você está ocupado pro rolê. Fique em casa codando! Esta carta anulará o próximo shot que mandarem você beber.', 1),
    (12, 1, 12, 'Renekton de Rei Destruído', 'shot', true, 'Ao buildar errado, o Jax conseguiu feedar mais uma vez. Escolha 4 jogadores, companheiros de time do Jax, para beberem 1 shot cada.', 2),
    (13, 1, 13, 'Roubando a Jurupinga', 'efeito', true, 'Roubaram uma jurupinga do Jax! Escolha 1 jogador para perde 1 shot de sua contagem e outro para beber 1 shot.', 2),
    (14, 1, 14, 'Cortador de Unhas', 'investigacao', false, 'Estão ouvindo um "clak" no discord? O Jax está cortando suas unhas de novo. Escolha 1 jogador e, se ele for o Sjehnsens, ele ficará sem jogar por 1 turno completo.', 2),
    (15, 1, 15, 'O Guerreiro Entregue', 'efeito', false, 'Parece que o guerreiro se entregou. Escolha 1 jogador para dormir e perder 2 turnos completos.', 3),
    (16, 1, 16, 'Não Dá Pra Tetudo', 'efeito', false, 'Não se pode tetudo nessa vida, porém, novas cartas sim. Descarte sua mão e pegue uma nova.', 4),
    (17, 1, 17, 'Vão Chegar uns Amigos Aqui em Casa', 'shot', true, 'Seus amigos chegaram e eles querem beber. Escolha 3 jogadores para beberem 1 shot cada.', 2),
    (18, 1, 18, 'Todos a Bordo!', 'shot', true, 'Piuííííí!!! Preparem-se para embarcar em uma grande aventura com o maquinista Stanley! Todos devem beber 1 shot.', 2),
    (19, 1, 19, 'Cebola Amiga', 'investigacao', true, 'O Ricardo finalmente fez as pazes com a cebola que quase o matou. Para comemorar essa reconciliação, Stanley se revelará, tomando 2 shot.', 4),
    (20, 1, 20, 'Dia do Legume', 'efeito', false, 'O dia do legume chegou e o pequeno Ricardinho vai ser um menino bonzinho e obediente! Após jogar esta carta, após 3 turnos, a missão de Stanley passará a depender da vitória de mais 2 jogadores.', 4),
    (21, 1, 21, 'Dj Vomitado', 'efeito', false, 'Seu amigo acabou de vomitar no Dj. Escolha 1 jogador para perder 2 shots de sua contagem.', 3),
    (22, 1, 22, 'Jogos Desnecessários', 'efeito', false, 'O Ricardo não compra jogos desnecessários, apenas os necessários. Por isso, você deve escolher 2 cartas, necessárias, que já foram usadas por você, e recolocar no seu baralho. Após a escolha, o baralho será embaralhado.', 3),
    (23, 1, 23, 'Tô Out', 'defesa', false, 'Hoje você quer ficar só na aguinha. Escolha outro jogador para beber 1 shot que você deveria beber.', 2),
    (24, 1, 24, 'Abraço na Árvore', 'investigacao', true, 'Faça como o Camelinho e celebre o amor pelo meio ambiente! Para isso, escolha 1 jogador para beber 1 shot. Se você ou o jogador escolhido for o Smichaels, você também toma 1 shot.', 3),
    (25, 1, 25, 'Viagem no Porta-Malas', 'efeito', false, 'Você foi viajar com o pessoal, mas acabou indo no porta-malas. Como recompensa, você deverá comprar 1 carta extra.', 1),
    (26, 1, 26, 'Que Mentira!', 'defesa', false, 'O jogo travou! Aumentou o FPS bem na hora! Tão usando hack! Esse boneco engordou! Seja qual for a razão, todos sabemos que habilidade não nos falta e, por este motivo, você pode cancelar qualquer jogada contra você que não tenha a ver com shots.', 4),
    (27, 1, 27, 'Papai Noel', 'shot', true, 'O Natal chegou! Presenteie outro jogador com 1 shot.', 1),
    (28, 1, 28, 'Luvas no Chão', 'shot', true, 'Você encontrou as luvas do Dron no chão e há 1 shot dentro delas. Beba-o.', 1),
    (29, 1, 29, 'É Aquela Velha História', 'shot', true, 'Não, sim, é o que eu digo pra vocês! Os 2 jogadores a sua esquerda devem beber 1 shot.', 2),
    (30, 1, 30, 'Peitos', 'shot', true, 'Você acaba de perceber que seu amigo está encarando os peitos de uma guria e, por isso, ele deve beber. O jogador mais distante de você deve beber 1 shot.', 1),
    (31, 1, 31, 'Bêbado de Shoyu', 'investigacao', true, 'Todo mundo tem um fraco para alguma bebida. A do Dron é o Molho Shoyu. Escolha 1 jogador para beber 1 shot e, se este jogador for o Sjamals, ele deverá beber 2 shots.', 3),
    (32, 1, 32, 'Quando Eu Fui pra Austrália...', 'efeito', false, 'Vivendo com os cangurus, o Dron obteve as mais intensas experiências, sexuais ou não, de sua vida. Escolha 2 jogadores para trocarem de missão entre si e terem também essa experiência marsupiana.', 3),
    (33, 1, 33, 'O Robin Brasileiro', 'efeito', false, 'Poucos sabem, mas há um super-herói entre nós. Sendo um menino prodígio, o Dron possui poderes de se transvestir que poucos superam. Ao jogar esta carta, você pode mimetizar os efeitos de qualquer carta já jogada anteriormente.', 4),
    (34, 1, 34, 'Vamos pra Baleia', 'efeito', false, 'Pedron Ourfali quer viajar com seus amigos. Escolha até 4 jogadores para fazerem uma viagem e, a seu critério, mude suas posições no jogo.', 3),
    (35, 1, 35, 'Disco de Duelo', 'efeito', false, 'O Dron nunca entregou o disco de duelo que ele nos vendeu. Como indenização, você pode olhar a última carta do seu baralho e decidir se quer compra-la ou comprar a do topo.', 2),
    (36, 1, 36, 'Cuidadron', 'defesa', false, 'Faça como o Dron e seja sempre safe nos jogos. Jogue esta carta e anule uma carta de efeito jogada contra você.', 2),
    (37, 1, 37, 'Caipa Dupla do Céu', 'shot', true, 'Hoje a caipa é dupla no Céu! Escolha 1 jogador para beber 1 shot com você.', 1),
    (38, 1, 38, 'Rolê', 'investigacao', true, 'Brasa, Jv e Jp estão no vip do Rolê, bebendo muita tequila. Os jogadores Swarley, Smichaels e Sauzburg deverão beber 1 shot cada, mas sem revelar suas identidades.', 3),
    (39, 1, 39, 'A Luta do Século', 'investigacao', true, 'Foi marcada a luta para finalmente decidir quem ganhou a briga na casa do Yuri. Para assistir esse duelo, todos os jogadores, com exceção de Sauzburg e Swarley, devem beber 1 shot.', 3),
    (40, 1, 40, 'Filtro do Snapchat', 'investigacao', false, 'Brasa e Jp adoram brincar com as novas tecnologias e se mamar depois. Sem revelar suas identidades, Swarley e Sauzburg deverão trocar suas missões um com o outro.', 3),
    (41, 1, 41, 'Show das Drags', 'investigacao', false, 'João Vitor e Brasa foram a um show de Drags na Cucko e se surpreenderam ao ver que seus amigos que eram as Drags. Os jogadores Sauzburg, Stanley e Sjehnsens deverão trocar de missão entre si, sem revelar suas identidades.', 3),
    (42, 1, 42, 'Client Perfeito', 'shot', true, 'Escolha 1 jogador para beber 2 shots. Era pra ser 1, mas o client bugou.', 1),
    (43, 1, 43, 'Piada do Milton', 'shot', true, 'O Senhor Milton é um piadista nato e, para homenagea-lo, o jogador anterior deve contar uma piada ou beber 2 shots.', 2),
    (44, 1, 44, 'Vamo virar? Vamo!', 'shot', true, 'Alguém lançou a ordem. Todos os jogadores bebem 1 shot. Simples.', 2),
    (45, 1, 45, 'Promoshare', 'shot', true, 'Você foi o grande sorteado da promoshare da Cucko, parabéns! Você e 2 acompanhantes ganharão free e 1 shot cada. Escolha 2 jogadores para beberem 1 shot com você.', 2),
    (46, 1, 46, 'Mãozinha', 'shot', true, 'Ao jogar esta carta, o último jogador desatento deverá beber 2 shots.', 2),
    (47, 1, 47, 'Ventilador Assassino', 'shot', true, 'O fim do ano chegou e mais um ventilador do Anne Frank caiu. Dessa vez, ele caiu no próximo jogador a jogar e ele deverá beber 1 shot para se curar.', 1),
    (48, 1, 48, 'Prisão', 'efeito', true, 'Assim como o sor de artes, um dos jogadores é um bandido. Escolha 1 jogador para ficar preso e sem poder jogar por 3 turnos completos, ou até que ele beba 2 shots.', 3),
    (49, 1, 49, 'Gemidinha', 'rápido', false, 'Ain!. Dê um gemidinho e anule qualquer jogada de qualquer jogador. Caso essa carta for usada fora da sua vez, o jogo continuará pelo jogador seguinte a você.', 4),
    (50, 1, 50, 'Modo Deus', 'efeito', false, 'Você acaba de ativar o "Modo Deus", um hack para jogadores medianos. Escolha 1 jogador e veja sua missão em segredo. Caso queira, você poderá trocar de missão com este jogador.', 4),
    (51, 1, 51, 'Sou Louca Sim!', 'efeito', false, 'O Jax duvidou, mas a vó Chucha mostrou pra ele quem é que manda, tirando este joguinho da tomada. A partir da ativação desta carta, o jogo durará mais 2 turnos completos e então terminará.', 4),
    (52, 1, 52, 'Cigarro no Olho', 'efeito', false, 'Se você quer foder seu adversário, apague um cigarro no olho dele. Escolha 1 jogador para roubar uma carta, sem vê-la. A carta será jogada imediatamente.', 3),
    (53, 1, 53, 'Xis do Gelson', 'efeito', false, 'O próximo jogador a jogar comeu um xis do Gelson e está de barriga cheia. Ele ficará sem jogar por 2 turnos completos para fazer a digestão.', 3),
    (54, 1, 54, 'Peido do Exequiel', 'efeito', false, 'Exequiel soltou um peido tão fedido que acabou confundindo os jogadores. A ordem de jogo será invertida.', 2),
    (55, 1, 55, 'A Queda', 'efeito', false, 'O Cauê caiu da escada e acabou levando junto 2 shots de alguém. Escolha 1 jogador para perder 2 shots de sua contagem.', 3),
    (56, 1, 56, 'O Político', 'efeito', false, 'Faça como o Fabrício e filie-se a um partido. A sua escolha, todos os jogadores deverão passar sua missão para o jogador anterior ou o seguinte.', 4),
    (57, 1, 57, 'A Prova Comida', 'efeito', false, 'Algumas pessoas resolveram comer sua prova. Escolha 1 jogador para perder o jogo, mesmo que ele cumpra sua missão. A carta perde o efeito após 2 turnos a partir do momento em que foi jogada.', 4),
    (58, 1, 58, 'Tábua do Joaquim', 'efeito', false, 'Os guris pilharam de comprar mais uma tábua, mas a divisão do custo sairá cara. Escolha 3 jogadores para descartarem 1 carta de suas mãos.', 3),
    (59, 1, 59, 'O Que?', 'defesa', false, 'Você acaba de ser confrontado, contudo está protegido perante sua total incredulidade. Anule até 2 shots que mandem você beber.', 2),
    (60, 1, 60, 'Ah Meu, Para!', 'defesa', false, 'Alguém já bebeu demais. Jogue está carta para bloquear 1 shot de qualquer jogador.', 2),
    (61, 1, 61, 'O Fio Vermelho', 'divino', true, 'O Fio Vermelho é um grande mistério, mas definitivamente poderoso. Use o poder do Fio para conectar 2 jogadores. Sempre que um beber um número de shots, o outro deverá beber também o mesmo número de shots.', 5),
    (62, 1, 62, 'Quinta Dimensão', 'divino', false, 'A partir da ativação desta carta, o próximo jogador a beber 5 shots, abrirá o portal para a Quinta Dimensão, ocasionando no encerramento da jornada quadridimensional e do jogo.', 5),
    (63, 1, 63, 'Benção de Gladstone', 'divino', false, '"Nem Gladstone muda este game". As palavras mágicas foram ditas e agora você tem o poder de trocar o número de shots de um jogador qualquer, com outro jogador qualquer.', 5),
    (64, 2, 1, 'Bitrix', 'equipamento', false, 'Um relógio esquisito grudou no seu pulso vindo lá do infinito, o Bitrix! Com ele você poderá escolher para si qualquer missão existente na partida, tendo esse efeito duradouro até o final do jogo ou até esta carta ser destruída. Sua carta de missão ainda poderá ser trocada.', 4),
    (65, 2, 2, 'Baguga ou Morte?', 'shot', true, 'Um náufrago azarado acaba de se deparar com uma tribo. Defina 1 jogador para escolher entre baguga ou morte. Baguga: beber 1 shot para cada adversário jogando. Morte: ficar sem jogar por 2 turnos completos, mas antes, baguga!', 4),
    (66, 2, 3, 'Que Papinho', 'defesa', false, 'Quando começarem de conversa mansa para cima de você, diga "que papinho". Isso negará o efeito de de um equipamento jogado por outro jogador, o destruindo.', 3),
    (67, 2, 4, 'Ricardo Goleiro 1', 'defesa', false, 'Como bom pelotense, o Ricardo adora agarrar bolas. Ao ser alvejado por algum efeito divino, jogue esta carta e seja defendido pelo melhor goleiro do Brasil. O efeito contra você será anulado.', 3),
    (68, 2, 5, 'Uma Noite de Fúria', 'investigacao', false, 'Cuidado! João Vitor está drogado na noite e está distribuindo socos! Selecione 2 jogadores e, se algum deles for Smichaels, na rodada do fim, Smichaels ganhará caso todos os outros tenham perdido. A carta perde o efeito após uma troca de missão de Smichaels.', 4),
    (69, 2, 6, 'Tchouameni', 'defesa', false, 'Faça como João Vitor e diga "Tchouameni". Essa ação pulará a jogada de qualquer jogador que estiver prestes a jogar.', 2),
    (70, 2, 7, 'Alelo do Dron', 'equipamento', true, 'Você adquiriu o cartão Alelo infinito do Dron e poderá pagar shots para si e para seus amigos. Uma vez por turno, em sua vez, você poderá escolher entre beber 1 shot extra ou escolher outro jogador para beber este shot extra.', 3),
    (71, 2, 8, 'Argentina Campeã', 'efeito', false, 'A Argentina acaba de ser campeã da Copa do Mundo e o Rafa enlouqueceu. Swelcows jogou tudo pro alto e, ao chegar na rodada do fim, vencerá o Jogo. A carta perde o efeito após uma troca de missão de Swelcows.', 3),
    (72, 2, 9, 'Boludos', 'investigacao', true, 'Argentinos são boludos e, por isso, Sjehnsens e Swelcows deverão beber 1 shot cada, sem revelar suas identidades.', 3),
    (73, 2, 10, 'Pixuco', 'equipamento', true, 'Um cachorro controverso. Equipe Pixuco a 1 jogador. Se este for Sjehnsens ou Swelcows, Pixuco cortará pela metade seus futuros shots, arredondando para cima. Caso seja um dos outros jogadores, Pixuco o obrigará a beber 1 shot extra a cada turno.', 3),
    (74, 2, 11, 'Extreme Zero', 'investigacao', true, 'A Extreme Zero voltou! Monte seu squad escolhendo 3 jogadores, pelas missões, para beber 1 shot com você. Os jogadores que estiverem com as missões escolhidas devem beber 1 shot, mas sem revelar suas identidades.', 3),
    (75, 2, 12, 'Vai Virar Uma Carta', 'shot', true, 'O grupo possui infinitas histórias. Sendo assim, invente uma nova carta que te permita escolher 1 jogador para beber 2 shots. Caso os outros jogadores achem uma carta ruim, você que bebe os 2 shots.', 2),
    (76, 2, 13, 'Divide e Multiplica', 'shot', true, 'Como bons alunos da Ana Ilha, todos nós sabemos que quem divide, multiplica. Beba 1 shot e escolha outro jogador para beber também. Este jogador deverá escolher mais 1 jogador para beber outro shot.', 2),
    (77, 2, 14, 'Atirador de Feijão do Gil', 'equipamento', true, 'Gil aprimorou seu atirador de feijão e agora ele atira shots. Uma vez por turno, na vez do jogador equipado com esta carta, ele poderá escolher qualquer jogador para beber 1 shot extra.', 3),
    (78, 2, 15, 'O Senhor dos Anéis', 'efeito', false, 'Emersauron surgiu no rolê e está falando do seu precioso. Escolha 1 jogador para ser amaldiçoado pelas palavras malignas de Emersauron e, por dois turnos completos, todo shot que ele beber, não contará em sua contagem.', 3),
    (79, 2, 16, 'Largando a Medicina', 'efeito', false, 'Que tristeza, parece que o Inhos largou a medicina. Para consolá-lo, você deverá dar metade dos shots de algum jogador para ele. Os shots remanescentes deverão ser arredondados para cima.', 4),
    (80, 2, 17, 'Bocejada da Fátima', 'efeito', false, 'A Fátima bocejou e acabou soprando o equipamento de um jogador. Transfira a posse de um equipamento de qualquer jogador para qualquer outro jogador.', 3),
    (81, 2, 18, 'A Árvore da Berlim', 'divino', false, 'Apesar de todas as intempéries do mundo: violência, guerras, desastres e a ganância da humanidade, a grande Árvore da Berlim continua de pé, distribuindo seu poder de resiliência. Ao jogar esta carta, anule todos os efeitos de ação prolongada ativas no momento.', 5),
    (82, 2, 19, 'FUDEU', 'divino', false, 'Dron foi resgatar o soldado Ryan em pleno Dia D, contudo, fudeu: uma bomba estourou e destruiu todos os equipamentos ativos no momento.', 5),
    (83, 3, 1, 'Pó de Pirlimpimpim', 'shot', true, 'A sininho enlouqueceu e quer jogar pó de pirlimpimpim (5 shots) em alguém. Escolha 1 jogador para beber 5 shots.', 3),
    (84, 3, 2, 'Freio de Ouro', 'efeito', false, 'Em plena segunda feira você está entendiado e resolveu, sem mais nem menos, ir na Freio de Ouro. Fique sem jogar por 2 turnos, mas imune à qualquer jogada.', 3),
    (85, 3, 3, 'Jp da Ganância', 'efeito', false, 'Compre 2 cartas. Nas próximas rodadas, haverá uma chance de 50% de você não poder comprar uma nova carta. Este efeito durará até o momento em que o número de cartas em sua mão se estabilize.', 2),
    (86, 3, 4, 'Caipirinha de Banana', 'shot', true, 'A Caipirinha de Banana do Jax é traiçoeira: doce por fora e horrível por dentro. O jogador com o maior número de shots fornecidos deve beber 2 shots extras.', 1),
    (87, 3, 5, 'Ao Infinito e Além', 'efeito', false, 'Buzz Lightyear levantou voo, rumo ao infinito e além. Escolha um jogador para ter sua contagem de shots elevada ao infinito por 2 turnos completos.', 4),
    (88, 3, 6, 'Vamos Fazer um Sorteio?', 'investigacao', false, 'Ricardo quis criar uma dinâmica diferente pro amigue secrete e acabou levando um boleto pra pagar. Ao utilizar essa carta, escolha 1 jogador para trocar de missão com ele. Este jogador escolherá outro jogador para trocar de missão e assim sucessivamente. As trocas pararão até alguém tentar realizar uma troca com Stanley.', 4),
    (89, 3, 7, 'Foto do Frango', 'efeito', false, 'A foto do seu frango fez sucesso e ganhou muitos likes. Escolha um jogador para lhe entregar uma carta, à escolha dele. Em seguida, você poderá jogar outra carta.', 2),
    (90, 3, 8, 'Tu Diz?', 'defesa', false, 'Ninguém entende direito essa expressão, mas ela tem poderes. Quando alguém usar alguma carta de shot contra você ou outro jogador, reverta os shots para o jogador que utilizou a carta.', 2),
    (91, 3, 9, '#CriseNaDiretoria', 'shot', true, 'Parece que o JV não conseguiu organizar o futebol de novo e o grupo está claramente em crise. Por conta disso, todos os jogadores que que possuam 5 ou mais shots, devem beber mais 1 shot.', 2),
    (92, 3, 10, 'Slides?', 'efeito', false, 'Finalmente rolará o tão pedido rolê de slides! Todos os jogadores mostrarão uma carta aleatória de sua mão para todos os outros jogadores.', 2),
    (93, 3, 11, 'Boleto do Dron', 'equipamento', true, 'O Dron passou um boleto de presente para alguém. Equipe esta carta a 1 jogador. Este jogador deverá beber 1 shot extra a cada turno. Após o primeiro shot, ele terá 50% de chance de beber outro. Caso beba o segundo, terá 25% de chance de beber o terceiro. Se o jogador beber 3 shots, o boleto será quitado e a carta destruída.', 3),
    (94, 3, 12, 'Cama Embaixo da Mesa', 'efeito', false, 'O Dron sabe muito bem que o melhor lugar para se dormir é embaixo de uma mesa. Ao jogar esta carta, você dormirá por 1 turno completo, não podendo jogar. Contudo, ao retornar ao jogo, você estará tão descansado que poderá jogar 2 cartas de uma vez.', 1),
    (95, 3, 13, 'Tatuagem de Shuriken', 'investigacao', true, 'O Rafa estava trovando uma menina, mas após ver sua tatuagem de otaku, ela resolveu pular fora. Por conta disso, Rafael irá beber. Swelcows e mais outro jogador, escolhido aleatoriamente (pois estava com sede no momento), beberão 1 shot.', 2),
    (96, 3, 14, 'Enem', 'efeito', false, 'Hoje não é dia de beber, pois amanhã tem Enem! Escolha 1 jogador para sofrer uma penalidade caso beba algum shot pelos próximos 2 turnos completos. Ao beber 1 shot, o jogador perderá aleatoriamente 1 carta de sua mão.', 3),
    (97, 3, 15, 'Maldição do Jogador', 'efeito', false, 'Não importa o quanto o Rafa se esforce, ele sempre acaba perdendo no futebol. Escolha 1 jogador para ser contaminado pela maldição do Rafa e, até uma troca de missão deste jogador, ele perderá caso o jogo acabe.', 3),
    (98, 3, 16, 'Separar e Procurar Pistas', 'investigacao', false, 'Daphne e Fred (Menzinho) resolveram se separar do grupo para "procurar pistas". Escolha 1 jogador e descubra a missão dele em segredo.', 3),
    (99, 3, 17, 'Pedido de Casamento', 'efeito', false, 'Iniciou-se a operação secreta do pedido de casamento! Escolha 1 jogador, em segredo, para se casar com você. Ao terminar a partida, o jogador escolhido vencerá ou perderá de acordo com o seu resultado. O efeito desta carta perdurará até que a morte os separem ou até que o efeito seja anulado por outra carta.', 4),
    (100, 3, 18, 'Uvas para Ressaca', 'efeito', false, 'Parece que alguém bebeu demais e está precisando dos poderes curativos das uvas. Escolha 1 jogador para perder metade de sua contagem de shots, arredondando para cima.', 3),
    (101, 3, 19, 'Valeu Valeu', 'rápido', true, 'Seu amigo fez uma jogada muito merda, mas não tem problema, pois você está com muito espírito esportivo e quer incentivá-lo. Diga "valeu valeu" e acrescente 1 shot para o alvo, ou alvos, do jogador atual.', 1),
    (102, 3, 20, 'Condimentos Vencidos', 'efeito', false, 'A galera foi para a sua casa e percebeu que os condimentos estavam vencidos. Por conta disso, escolha 1 jogador para expulsar do jogo. Ele não poderá jogar até o momento em que tomar 3 shots.', 3),
    (103, 3, 21, 'Vamos pra Argentina', 'efeito', false, 'Mais um ano se passou e mais uma viagem pra Argentina não aconteceu. Anule a jogada do jogador anterior a você.', 3),
    (104, 3, 22, 'Leo Noites', 'efeito', false, 'O famoso jornalista Leo Noites atacou mais uma vez e descobriu as farras dos jogadores. Escolha 1 efeito prolongado que esteja ativo no momento e destrua-o.', 3),
    (105, 3, 23, 'Não é o Momento', 'defesa', false, 'Todos sabem que a hora da pizza é sagrada e que não é o momento para brigas. Interrompa a jogada de outro jogador que fizer uma ação contra um outro jogador.', 3),
    (106, 3, 24, 'Eu Sou o Lucas', 'shot', true, 'Aleatoriamente o Lucas apareceu no rolê e quer beber. 1 jogador aleatório irá beber 1 shot.', 1),
    (107, 3, 25, 'Vendedor de Drogas', 'efeito', true, 'Brotou esse mano em Summoners Rift e ninguém sabe direito o que ele faz. Escolha 1 dos seguintes efeitos: Faça 1 jogador beber 1 shot ou retire 1 shot da contagem de 1 jogador.', 2),
    (108, 3, 26, 'Boina', 'equipamento', false, 'A boina do Tom Joboina é um item lendário, com incríveis magias de fixação na cabeça. Equipe ela em si mesmo ou em outro jogador e não será possível alterar a missão do jogador equipado.', 4),
    (109, 3, 27, 'Paz Terrível', 'divino', false, 'O jogo está indo muito bem, mas você não está em paz. Jogue esta carta e sinta a paz terrível, pois caso o jogo encerre dentro das próximas 2 rodadas, todos perderão, exceto você, que vencerá sozinho.', 5),
    (110, 3, 28, 'Petricor', 'divino', false, 'Está sentindo este cheiro de terra molhada e cocô de cachorro? Sim, isso é o Petricor! Um cheiro capaz de mudar os rumos do jogo! Jogue esta carta e intoxique 1 jogador qualquer, zerando os shots dele.', 5),
    (111, 3, 29, 'Gladsxódia #1', 'shot', true, 'Sauzburg está tentando invocar o Gladsxódia! Ao jogar esta carta, escolha 1 jogador para beber 1 shot. Caso você reúna todas as cartas de Gladsxódia, dos números 1 ao 6, em sua mão, você vencerá o jogo automaticamente, sozinho. O jogo então será finalizado com a fúria de Glads.', 1),
    (112, 3, 30, 'Gladsxódia #2', 'shot', true, 'Sjamals está tentando invocar o Gladsxódia! Ao jogar esta carta, escolha 1 jogador para beber 1 shot. Caso você reúna todas as cartas de Gladsxódia, dos números 1 ao 6, em sua mão, você vencerá o jogo automaticamente, sozinho. O jogo então será finalizado com a fúria de Glads.', 1),
    (113, 3, 31, 'Gladsxódia #3', 'shot', true, 'Smichaels está tentando invocar o Gladsxódia! Ao jogar esta carta, escolha 1 jogador para beber 1 shot. Caso você reúna todas as cartas de Gladsxódia, dos números 1 ao 6, em sua mão, você vencerá o jogo automaticamente, sozinho. O jogo então será finalizado com a fúria de Glads.', 1),
    (114, 3, 32, 'Gladsxódia #4', 'shot', true, 'Stanley está tentando invocar o Gladsxódia! Ao jogar esta carta, escolha 1 jogador para beber 1 shot. Caso você reúna todas as cartas de Gladsxódia, dos números 1 ao 6, em sua mão, você vencerá o jogo automaticamente, sozinho. O jogo então será finalizado com a fúria de Glads.', 1),
    (115, 3, 33, 'Gladsxódia #5', 'shot', true, 'Swelcows está tentando invocar o Gladsxódia! Ao jogar esta carta, escolha 1 jogador para beber 1 shot. Caso você reúna todas as cartas de Gladsxódia, dos números 1 ao 6, em sua mão, você vencerá o jogo automaticamente, sozinho. O jogo então será finalizado com a fúria de Glads.', 1),
    (116, 3, 34, 'Gladsxódia #6', 'shot', true, 'Sjehnsens está tentando invocar o Gladsxódia! Ao jogar esta carta, escolha 1 jogador para beber 1 shot. Caso você reúna todas as cartas de Gladsxódia, dos números 1 ao 6, em sua mão, você vencerá o jogo automaticamente, sozinho. O jogo então será finalizado com a fúria de Glads.', 1);
